import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { JSDOM } from 'jsdom';

const require_ = createRequire(import.meta.url);
const axeSource = readFileSync(require_.resolve('axe-core/axe.min.js'), 'utf8');

const HEADING_TAGS = new Set(['H1', 'H2', 'H3', 'H4', 'H5', 'H6']);

/**
 * Elements considered natively focusable (plus anything with an explicit
 * tabindex attribute).
 */
function isFocusable(el) {
  const tag = el.tagName.toUpperCase();
  if (tag === 'A' || tag === 'AREA') return Boolean(el.getAttribute('href'));
  if (
    tag === 'BUTTON' ||
    tag === 'INPUT' ||
    tag === 'SELECT' ||
    tag === 'TEXTAREA'
  ) {
    // disabled form controls are not focusable
    return !el.hasAttribute('disabled');
  }
  if (tag === 'IFRAME') return true;
  return el.hasAttribute('tabindex');
}

/** Heading levels must not skip (e.g. h1 -> h3). */
function findHeadingSkips(document) {
  const findings = [];
  let previousLevel = null;
  const headings = Array.from(
    document.querySelectorAll('h1, h2, h3, h4, h5, h6')
  );
  for (const heading of headings) {
    const level = Number(heading.tagName.charAt(1));
    if (previousLevel !== null && level > previousLevel + 1) {
      findings.push({
        type: 'heading-skip',
        message: `Heading level skipped from h${previousLevel} to h${level}`,
        previous: `h${previousLevel}`,
        current: `h${level}`,
      });
    }
    previousLevel = level;
  }
  return findings;
}

/**
 * Elements with a click-suggesting class (class token containing "btn") must be
 * buttons, links, or otherwise focusable.
 */
function findFakeButtons(root) {
  const findings = [];
  const candidates = Array.from(root.querySelectorAll('*')).filter((el) =>
    Array.from(el.classList).some((token) => token.toLowerCase().includes('btn'))
  );
  for (const el of candidates) {
    const tag = el.tagName.toUpperCase();
    if (isFocusable(el)) continue;
    findings.push({
      type: 'clickable-not-focusable',
      message: `Element <${tag.toLowerCase()} class="${el.getAttribute(
        'class'
      )}"> looks clickable but is not a button, link, or focusable element`,
      tag: tag.toLowerCase(),
      className: el.getAttribute('class'),
    });
  }
  return findings;
}

function describeViolation(violation) {
  return {
    id: violation.id,
    impact: violation.impact ?? null,
    description: violation.description,
    help: violation.help,
    nodes: violation.nodes.map((node) => ({
      target: node.target,
      html: node.html,
    })),
  };
}

/**
 * Audit an HTML string with axe-core plus custom checks.
 *
 * @param {string} html
 * @returns {Promise<{violations: object[], custom: object[]}>}
 */
export async function auditHtml(html) {
  const dom = new JSDOM(html, {
    runScripts: 'outside-only',
    pretendToBeVisual: true,
  });
  const { window } = dom;

  try {
    // Load axe-core into the jsdom window.
    window.eval(axeSource);
    if (!window.axe) {
      throw new Error('Failed to initialize axe-core inside jsdom');
    }

    const axeResult = await window.axe.run(window.document);

    const violations = axeResult.violations.map(describeViolation);

    const custom = [
      ...findHeadingSkips(window.document),
      ...findFakeButtons(window.document.body),
    ];

    return { violations, custom };
  } finally {
    window.close();
  }
}

export default auditHtml;

