import { describe, it, expect } from 'vitest';
import { auditHtml } from '../src/audit.js';

// Full documents (lang, title, main landmark) so that page-level axe rules
// pass and only genuine issues surface.
const KNOWN_BAD = `<!DOCTYPE html>
<html lang="en">
<head><title>Bad</title></head>
<body>
<main>
  <h1>Shipping</h1>
  <h3>Skipped straight past h2</h3>
  <div class="btn btn-primary">Click me</div>
  <img src="chart.png">
</main>
</body>
</html>`;

const KNOWN_GOOD = `<!DOCTYPE html>
<html lang="en">
<head><title>Good</title></head>
<body>
<main>
  <h1>Shipping</h1>
  <h2>Details</h2>
  <button type="button" class="btn btn-primary">Save</button>
  <a href="/more" class="link-btn">More</a>
  <img src="chart.png" alt="Quarterly revenue chart">
</main>
</body>
</html>`;

describe('auditHtml', () => {
  it('flags exactly the expected violations and custom findings on a known-bad page', async () => {
    const report = await auditHtml(KNOWN_BAD);

    expect(report.violations.map((v) => v.id)).toEqual(['image-alt']);

    expect(report.custom).toEqual([
      {
        type: 'heading-skip',
        message: 'Heading level skipped from h1 to h3',
        previous: 'h1',
        current: 'h3',
      },
      {
        type: 'clickable-not-focusable',
        message:
          'Element <div class="btn btn-primary"> looks clickable but is not a button, link, or focusable element',
        tag: 'div',
        className: 'btn btn-primary',
      },
    ]);
  });

  it('returns empty arrays on a known-good page', async () => {
    const report = await auditHtml(KNOWN_GOOD);

    expect(report.violations).toEqual([]);
    expect(report.custom).toEqual([]);
  });

  it('closes the jsdom window cleanly', async () => {
    const report = await auditHtml(KNOWN_GOOD);

    expect(report).toBeDefined();
    expect(Object.keys(report).sort()).toEqual(['custom', 'violations']);
    // No dangling timers/process refs: suite exits without --forceExit.
  });
});

